// Re-print a sample barcode label  (permissions: lab.sample.collect)
export const label = (sample_id) =>
  api("GET", `/lab/samples/${sample_id}/label`, undefined);   // api(): see get_guide('envelope-and-errors')

// Scanner lookup → metric grid with this patient's reference ranges  (permissions: lab.sample.receive, lab.result.enter)
export const scanLab = (barcode) =>
  api("GET", `/lab/scan/${barcode}`, undefined);   // api(): see get_guide('envelope-and-errors')

// Collect a sample → returns the barcode label print payload  (permissions: lab.sample.collect)
export const collectLabSamples = (sample_id, body) =>
  api("POST", `/lab/samples/${sample_id}/collect`, body);   // api(): see get_guide('envelope-and-errors')

// Mark the sample received in the lab (item → Processing)  (permissions: lab.sample.receive)
export const receiveLabSamples = (sample_id, body) =>
  api("POST", `/lab/samples/${sample_id}/receive`, body);   // api(): see get_guide('envelope-and-errors')

// Results awaiting verification (critical & STAT first)  (permissions: lab.result.verify)
export const verificationQueue = () =>
  api("GET", `/lab/verification-queue`, undefined);   // api(): see get_guide('envelope-and-errors')

// Verify (publish + notify doctor) or reject back to the bench  (permissions: lab.result.verify)
export const verifyLabResults = (result_id, body) =>
  api("POST", `/lab/results/${result_id}/verify`, body);   // api(): see get_guide('envelope-and-errors')
